class Solution(object):
    def minFlipsMonoIncr(self, s):
        """
        :type s: str
        :rtype: int
        """
        dp0 = dp1 = 0
        for i in range(len(s)):
            new_dp0, new_dp1 = dp0, min(dp0, dp1)
            if s[i] == "0":
                new_dp1 += 1
            else:
                new_dp0 += 1
            dp0, dp1 = new_dp0, new_dp1
        return min(dp0, dp1)
